function consensusValidHash(value) {
  return typeof value === 'string' && /^[a-f0-9]{64}$/i.test(value) ? value.toLowerCase() : null;
}

export function makeConsensusReports({ baselineHash = null, currentHash = null, mode = 'baseline' } = {}) {
  const trusted = consensusValidHash(baselineHash) ?? consensusDefaultBaseline;
  const received = consensusValidHash(currentHash);
  const sampleVariant = consensusDefaultVariant === trusted ? consensusDefaultBaseline : consensusDefaultVariant;
  const variant = received && received !== trusted ? received : sampleVariant;
  return consensusNodes.map((node) => ({
    ...node,
    hash: mode === 'synchronized' || (mode === 'regional' && node.region === 'us-west') ? variant : trusted,
  }));
}

export function aggregateConsensus(reports, { baselineHash = null, currentHash = null, mode = 'baseline' } = {}) {
  const trusted = consensusValidHash(baselineHash) ?? consensusDefaultBaseline;
  const received = consensusValidHash(currentHash);
  const votes = new Map();
  const anomalyRegions = new Set();
  let anomalyCount = 0;
  for (const { hash, region } of reports) {
    votes.set(hash, (votes.get(hash) ?? 0) + 1);
    if (hash !== trusted) {
      anomalyCount++;
      anomalyRegions.add(region);
    }
  }
  const sorted = [...votes].sort((left, right) => right[1] - left[1]);
  const [leadingHash = null, majorityCount = 0] = sorted[0] ?? [];
  const majorityHash = majorityCount > reports.length / 2 ? leadingHash : null;
  return {
    mode, nodeCount: reports.length, normalCount: reports.length - anomalyCount, anomalyCount,
    consensusRatio: reports.length ? majorityCount / reports.length : 0,
    consensusHash: majorityHash, baselineHash: trusted, currentHash: received, anomalyRegions: [...anomalyRegions],
    consensusMatchesBaseline: majorityHash ? majorityHash === trusted : null,
    currentMatchesConsensus: received && majorityHash ? received === majorityHash : null,
    currentMatchesBaseline: received ? received === trusted : null,
  };
}

function consensusHtml(tag, text, className) {
  const el = document.createElement(tag);
  if (text !== null && text !== undefined) el.textContent = text;
  if (className) el.className = className;
  return el;
}

function consensusSvg(tag, attrs = {}) {
  const el = document.createElementNS(consensusSvgNs, tag);
  for (const [name, value] of Object.entries(attrs)) el.setAttribute(name, value);
  return el;
}

function consensusXY(lon, lat) {
  return [(lon + 180) * (1000 / 360), 12 + (85 - lat) * 2.72];
}

